WITH target_kind AS (
  SELECT product_kind_id FROM product_kinds WHERE product_kind_name = 'Work Trousers'
),
linz_stores AS (
  SELECT store_id FROM stores WHERE city = 'Linz' AND is_open = 1 AND store_name LIKE '%PowerTool%'
),
eligible_inventory AS (
  SELECT DISTINCT product_sku FROM store_inventory WHERE store_id IN (SELECT store_id FROM linz_stores) AND available_today_quantity > 0
)
SELECT COUNT(DISTINCT v.product_sku) AS count
FROM product_variants v
JOIN target_kind k ON v.product_kind_id = k.product_kind_id
WHERE v.product_sku IN (SELECT product_sku FROM eligible_inventory);
